### 依赖项漏洞管理
```python
#!/usr/bin/env python3
"""
用于 CI/CD 流水线的依赖项安全扫描器集成。
封装多个 SCA 工具并强制执行组织策略。
"""

import json
import subprocess
import sys
from dataclasses import dataclass
from enum import Enum
from pathlib import Path


class Severity(Enum):
    CRITICAL = "critical"
    HIGH = "high"
    MEDIUM = "medium"
    LOW = "low"


@dataclass
class VulnFinding:
    package: str
    version: str
    severity: Severity
    cve: str
    fixed_version: str
    description: str
    exploitable: bool = False


class DependencyScanner:
    """带策略强制执行的统一依赖项扫描。"""

    # SLA: 按严重度分级的最大修复天数
    REMEDIATION_SLA = {
        Severity.CRITICAL: 7,
        Severity.HIGH: 30,
        Severity.MEDIUM: 90,
        Severity.LOW: 180,
    }

    # 已知的误报或已接受的风险（附有理由说明）
    SUPPRESSED = {
        "CVE-2023-XXXXX": "在我们的配置下不可被利用 — 已于 2024-01-15 由 AppSec 团队验证",
    }

    def scan_npm(self, project_path: Path) -> list[VulnFinding]:
        """使用 npm audit 扫描 Node.js 依赖项。"""
        result = subprocess.run(
            ["npm", "audit", "--json", "--production"],
            cwd=project_path, capture_output=True, text=True
        )
        findings = []
        if result.stdout:
            audit = json.loads(result.stdout)
            for vuln_id, vuln in audit.get("vulnerabilities", {}).items():
                findings.append(VulnFinding(
                    package=vuln_id,
                    version=vuln.get("range", "unknown"),
                    severity=Severity(vuln.get("severity", "low")),
                    cve=vuln.get("via", [{}])[0].get("url", "N/A") if vuln.get("via") else "N/A",
                    fixed_version=vuln.get("fixAvailable", {}).get("version", "N/A")
                        if isinstance(vuln.get("fixAvailable"), dict) else "N/A",
                    description=vuln.get("via", [{}])[0].get("title", "")
                        if isinstance(vuln.get("via", [None])[0], dict) else str(vuln.get("via", "")),
                ))
        return findings

    def scan_python(self, project_path: Path) -> list[VulnFinding]:
        """使用 pip-audit 扫描 Python 依赖项。"""
        result = subprocess.run(
            ["pip-audit", "--format=json", "--desc"],
            cwd=project_path, capture_output=True, text=True
        )
        findings = []
        if result.stdout:
            for vuln in json.loads(result.stdout):
                findings.append(VulnFinding(
                    package=vuln["name"],
                    version=vuln["version"],
                    severity=Severity.HIGH,  # pip-audit 并不总是提供严重度
                    cve=vuln.get("id", "N/A"),
                    fixed_version=vuln.get("fix_versions", ["N/A"])[0],
                    description=vuln.get("description", ""),
                ))
        return findings

    def enforce_policy(self, findings: list[VulnFinding]) -> tuple[bool, list[str]]:
        """
        将组织策略应用于扫描结果。
        返回 (通过/失败, 策略违规列表)。
        """
        violations = []
        for f in findings:
            # 跳过已压制的 CVE
            if f.cve in self.SUPPRESSED:
                continue

            # 严重和高危且存在已知修复方案 = 必须阻断
            if f.severity in (Severity.CRITICAL, Severity.HIGH) and f.fixed_version != "N/A":
                violations.append(
                    f"BLOCKED: {f.package}@{f.version} has {f.severity.value} "
                    f"vulnerability {f.cve} — fix available: {f.fixed_version}"
                )

            # 严重但无修复方案 = 警告但允许（需跟踪）
            elif f.severity == Severity.CRITICAL and f.fixed_version == "N/A":
                violations.append(
                    f"WARNING: {f.package}@{f.version} has CRITICAL vulnerability "
                    f"{f.cve} with no fix available — track for remediation"
                )

        passed = not any("BLOCKED" in v for v in violations)
        return passed, violations


def main():
    scanner = DependencyScanner()
    project = Path(".")

    # 检测项目类型并进行扫描
    findings = []
    if (project / "package.json").exists():
        findings.extend(scanner.scan_npm(project))
    if (project / "requirements.txt").exists() or (project / "pyproject.toml").exists():
        findings.extend(scanner.scan_python(project))

    # 强制执行策略
    passed, violations = scanner.enforce_policy(findings)

    for v in violations:
        print(v)

    print(f"\nTotal findings: {len(findings)}")
    print(f"Policy violations: {len(violations)}")
    print(f"Result: {'PASS' if passed else 'FAIL'}")

    sys.exit(0 if passed else 1)


if __name__ == "__main__":
    main()
```

### 威胁模型模板 (STRIDE)
```markdown
# 威胁模型: [功能/系统名称]

## 系统概览
**描述**: [此系统做什么]
**数据分级**: [公开 / 内部 / 机密 / 受限]
**合规范围**: [PCI-DSS / HIPAA / SOC 2 / 无]

## 架构图
[包含或引用一个展示组件、信任边界及数据流的数据流图]

## 资产
| 资产 | 分级 | 位置 | 负责人 |
|-------|---------------|----------|-------|
| 用户凭证 | 受限 | 认证服务数据库 | 身份团队 |
| 支付数据 | 受限 (PCI) | 支付处理器 | 支付团队 |
| 用户个人资料 | 机密 | 主数据库 | 产品团队 |

## 信任边界
1. 互联网 → 负载均衡器（不受信 → 半可信）
2. 负载均衡器 → API 网关（半可信 → 可信）
3. API 网关 → 内部服务（可信 → 可信）
4. 内部服务 → 数据库（可信 → 受限）

## STRIDE 分析

### 仿冒 (认证)
| 威胁 | 组件 | 风险 | 缓解措施 |
|--------|-----------|------|------------|
| 窃取的 JWT 被用于冒充用户 | API 网关 | 高 | 短寿命令牌 (15分钟), 刷新令牌轮换, 令牌绑定至 IP 范围 |
| API 密钥泄漏在客户端代码中 | 移动应用 | 高 | 使用 OAuth2 PKCE 流程, 绝不在客户端应用中嵌入密钥 |

### 篡改 (完整性)
| 威胁 | 组件 | 风险 | 缓解措施 |
|--------|-----------|------|------------|
| 请求体在传输中被修改 | 所有 API | 中 | 强制启用 TLS 1.3, 对敏感操作使用 HMAC 签名 |
| 数据库记录被攻击者修改 | 数据库 | 严重 | 参数化查询, 行级安全性, 审计日志 |

### 否认 (审计)
| 威胁 | 组件 | 风险 | 缓解措施 |
|--------|-----------|------|------------|
| 用户否认进行过某笔交易 | 支付服务 | 高 | 具有时间戳和用户操作签名的不可篡改审计日志 |
| 管理员否认更改过权限 | 管理员面板 | 中 | 管理员操作记录到仅追加存储，并附带管理员身份 |

### 信息泄露 (机密性)
| 威胁 | 组件 | 风险 | 缓解措施 |
|--------|-----------|------|------------|
| 错误消息暴露堆栈回溯 | API 响应 | 中 | 生产环境返回通用错误响应，详细的日志仅在服务端记录 |
| 通过 SQL 注入导致数据库数据转储 | 用户搜索 | 严重 | 参数化查询, WAF 规则, 输入验证 |

### 拒绝服务 (可用性)
| 威胁 | 组件 | 风险 | 缓解措施 |
|--------|-----------|------|------------|
| API 速率限制绕过 | API 网关 | 高 | 按用户进行速率限制, 请求大小限制, 强制执行分页 |
| 通过特制输入导致 ReDoS | 输入验证 | 中 | 使用 RE2 (线性时间正则), 输入长度限制 |

### 权限提升 (授权)
| 威胁 | 组件 | 风险 | 缓解措施 |
|--------|-----------|------|------------|
| IDOR: 用户访问其他用户的数据 | 个人资料 API | 严重 | 每次请求进行授权检查, 所有权验证 |
| 批量赋值: 用户自行设置管理员角色 | 用户更新 API | 高 | 显式定义可更新字段白名单, 绝不要将请求体直接绑定到模型 |

## 安全需求 (产出于此威胁模型)
1. [ ] 实现 JWT 令牌绑定，15 分钟过期
2. [ ] 为所有数据库操作添加参数化查询
3. [ ] 为所有状态变更操作启用审计日志
4. [ ] 实现按用户速率限制 (默认 100 次/分钟)
5. [ ] 添加验证资源所有权的授权中间件
6. [ ] 在生产环境的 API 错误响应中剔除敏感字段
